INSERT INTO public.event (id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status)
SELECT id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status FROM jsonb_populate_recordset(NULL::public.event, '[{"title": "朱延寿突至蕲州围城", "start_year": 896, "end_year": 896, "time_original": "896年五月条；确日未载", "dynasty": "唐", "description": "淮南将朱延寿突然到达蕲州，包围城池。", "phases": [], "location_name": "蕲州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "9673f32e-7405-5f1c-ad24-084441ef8b45"}, {"title": "贾公铎出猎不得还，伏兵林中", "start_year": 896, "end_year": 896, "time_original": "896年蕲州被围时；确日未载", "dynasty": "唐", "description": "贾公铎当时在外打猎，不能回城，将兵伏于林中。", "phases": [], "location_name": "蕲州城外林中", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "3f509b2e-8550-5e22-9f02-2510e328e58a"}, {"title": "贾公铎遣二勇士衣羊皮潜入城，约开门举火", "start_year": 896, "end_year": 896, "time_original": "896年蕲州围攻时夜间；确日未载", "dynasty": "唐", "description": "贾公铎命两名勇士穿羊皮，夜入朱延寿掠来的羊群，潜入城中约定夜半开门举火响应，再穿羊皮返回复命。", "phases": [], "location_name": "蕲州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "6d6ef884-17b8-55f3-a0e5-e9f82bf1da47"}, {"title": "贾公铎按火号力战，突围入城", "start_year": 896, "end_year": 896, "time_original": "896年围攻条；按约之夜", "dynasty": "唐", "description": "贾公铎按约率兵至城南，见门中举火，力战突破包围进入城内。", "phases": [], "location_name": "蕲州城南", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "ccb8ead7-5c37-52cc-b6f6-e8ef8ef4e3dc"}, {"title": "朱延寿请遣贾公铎故旧持誓书金帛劝降，许以婚", "start_year": 896, "end_year": 896, "time_original": "896年贾公铎突围入城以后；确日未载", "dynasty": "唐", "description": "朱延寿惊于贾公铎突围而入，认为城难速取，向杨行密请求选军中与贾公铎有旧者，持誓书金帛劝说，并许以婚姻。", "phases": [], "location_name": null, "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "原文未给单一地点。", "status": "draft", "id": "be880d7a-11bf-5ed2-883e-620ecc6d70f7"}, {"title": "柴再用请行，临城向贾公铎陈利害", "start_year": 896, "end_year": 896, "time_original": "896年朱延寿请劝降后；确日未载", "dynasty": "唐", "description": "寿州团练副使柴再用主动请求前往，临城与贾公铎交谈，陈说利害。", "phases": [], "location_name": "蕲州城前", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "8fc94437-f9c3-5b34-a1d6-ba26107307ef"}, {"title": "贾公铎冯敬章数日后请降", "start_year": 896, "end_year": 896, "time_original": "896年柴再用劝说后数日；确日未载", "dynasty": "唐", "description": "数日后，贾公铎和刺史冯敬章请求投降。", "phases": [], "location_name": "蕲州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "61c17f45-9fe2-5e93-ad1b-722f8db5d359"}, {"title": "冯敬章为左都押牙，贾公铎为右监门卫将军", "start_year": 896, "end_year": 896, "time_original": "896年蕲州请降后；确日未载", "dynasty": "唐", "description": "冯敬章被任为左都押牙，贾公铎被任为右监门卫将军。", "phases": [], "location_name": null, "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "原文未给单一地点。", "status": "draft", "id": "f0a99b67-383f-5984-9752-c4d55f0a8807"}, {"title": "朱延寿进拔光州，杀刺史刘存", "start_year": 896, "end_year": 896, "time_original": "896年蕲州请降及任职以后；确日未载", "dynasty": "唐", "description": "朱延寿继续攻取光州，杀刺史刘存。", "phases": [], "location_name": "光州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "0fcc1647-950d-5878-a9eb-a61a5c4c92f2"}, {"title": "唐昭宗遣中使赴梓州和解两川", "start_year": 896, "end_year": 896, "time_original": "896年五月丙戌", "dynasty": "唐", "description": "唐昭宗派中使前往梓州，调解两川。", "phases": [], "location_name": "梓州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "2615d6ff-3e62-5b82-b4c0-e3b2d94e7717"}, {"title": "王建奉诏回成都，两川仍连兵未解", "start_year": 896, "end_year": 896, "time_original": "896年五月丙戌和解条；奉诏还确日未另载", "dynasty": "唐", "description": "王建虽奉诏回成都，两川仍继续交战，战事未解。", "phases": [], "location_name": "成都", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "3ae910fa-7641-5701-ad81-35a3e9eb8206"}, {"title": "崔昭纬再次向朱温求救", "start_year": 896, "end_year": 896, "time_original": "896年五月戊子赐死前条；确日未载", "dynasty": "唐", "description": "崔昭纬再次向朱温请求救助。", "phases": [], "location_name": null, "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "原文未给单一地点。", "status": "draft", "id": "52328e3f-f07e-5d05-96c9-2fa691f35e79"}, {"title": "唐昭宗遣中使赐崔昭纬死", "start_year": 896, "end_year": 896, "time_original": "896年五月戊子", "dynasty": "唐", "description": "唐昭宗遣中使赐崔昭纬死。", "phases": [], "location_name": null, "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "原文未给单一地点。", "status": "draft", "id": "9a023501-f21b-5564-b64d-9f9cdaf175dd"}, {"title": "中使行至荆南追及崔昭纬，斩之", "start_year": 896, "end_year": 896, "time_original": "896年五月戊子遣使以后；追及确日未另载", "dynasty": "唐", "description": "中使到荆南，追上崔昭纬并将他斩杀。主书记中外均以为快。", "phases": [], "location_name": "荆南", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "e69437fb-76fe-57f0-8748-3e1ad4e4b29a"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

