INSERT INTO public.fact_claim (id, subject_table, subject_id, field_path, claim_text, source_id, citation, note, status)
SELECT id, subject_table, subject_id, field_path, claim_text, source_id, citation, note, status FROM jsonb_populate_recordset(NULL::public.fact_claim, '[{"subject_table": "event", "field_path": "description", "claim_text": "淮南将朱延寿突然到达蕲州，包围城池。", "citation": "卷260·乾宁三年（896）·zztj-v260-y0896-p018·原文件第99行", "note": "原文：淮南将硃延寿奄至蕲州，围其城。；核对说明：按本段原文整理，不补写未载的月日、地点或人物完整生平。", "status": "draft", "id": "67e93d9d-17b6-52d2-9a4d-87c52215ffdc", "subject_id": "9673f32e-7405-5f1c-ad24-084441ef8b45", "source_id": "98469cf2-27e5-5352-a615-5b7be1937da0"}, {"subject_table": "event", "field_path": "time_original", "claim_text": "896年五月条；确日未载", "citation": "卷260·乾宁三年（896）·zztj-v260-y0896-p018·原文件第99行", "note": "原文：淮南将硃延寿奄至蕲州，围其城。；核对说明：干支日未换算公历日。", "status": "draft", "id": "b918c46e-81fb-5202-927f-d06515462daa", "subject_id": "9673f32e-7405-5f1c-ad24-084441ef8b45", "source_id": "98469cf2-27e5-5352-a615-5b7be1937da0"}, {"subject_table": "person", "field_path": "description", "claim_text": "本段记朱延寿：围城将。", "citation": "卷260·乾宁三年（896）·zztj-v260-y0896-p018·原文件第99行", "note": "原文：淮南将硃延寿奄至蕲州，围其城。大将贾公鐸方猎，不得还，伏兵林中，命勇士二人衣羊皮夜入延寿所掠羊群，潜入城，约夜半开门举火为应，复衣皮返命。公鐸如期引兵至城南，门中火举，力战，突围而入。延寿惊曰：“吾常恐其溃围而出，反溃围而入，如此，城安可猝拔！”乃白行密，求军中与公鐸有旧者持誓书金帛往说之，许以婚。寿州团练副使柴再用请行，临城与语，为陈利害。数日，公鐸及刺史冯敬章请降。以敬章为左都押牙，公鐸为右监门卫将军。延寿进拔光州，杀刺吏刘存。；核对说明：按本段原文整理，不补写未载的月日、地点或人物完整生平。", "status": "draft", "id": "a1177d13-dabd-571b-8f4a-61714b820536", "subject_id": "6959c029-8c09-5670-bd4a-ace827cbbea8", "source_id": "98469cf2-27e5-5352-a615-5b7be1937da0"}, {"subject_table": "person_event", "field_path": "role", "claim_text": "朱延寿：围城将。", "citation": "卷260·乾宁三年（896）·zztj-v260-y0896-p018·原文件第99行", "note": "原文：淮南将硃延寿奄至蕲州，围其城。；核对说明：按本段原文整理，不补写未载的月日、地点或人物完整生平。", "status": "draft", "id": "120822ac-cd89-5e28-8878-ce7c0004d21a", "subject_id": "2fcefdf8-6317-558a-bdc6-dee35ff3684b", "source_id": "98469cf2-27e5-5352-a615-5b7be1937da0"}, {"subject_table": "event", "field_path": "description", "claim_text": "贾公铎当时在外打猎，不能回城，将兵伏于林中。", "citation": "卷260·乾宁三年（896）·zztj-v260-y0896-p018·原文件第99行", "note": "原文：大将贾公鐸方猎，不得还，伏兵林中；核对说明：大将所指贾公铎，不因公铎名相近合并后蜀张公铎；林中位置未配坐标。", "status": "draft", "id": "f031c300-17b5-5709-8852-a8ded5125cee", "subject_id": "3f509b2e-8550-5e22-9f02-2510e328e58a", "source_id": "98469cf2-27e5-5352-a615-5b7be1937da0"}, {"subject_table": "event", "field_path": "time_original", "claim_text": "896年蕲州被围时；确日未载", "citation": "卷260·乾宁三年（896）·zztj-v260-y0896-p018·原文件第99行", "note": "原文：大将贾公鐸方猎，不得还，伏兵林中；核对说明：大将所指贾公铎，不因公铎名相近合并后蜀张公铎；林中位置未配坐标。", "status": "draft", "id": "79826468-eb8c-56cc-9235-2fcdd7369275", "subject_id": "3f509b2e-8550-5e22-9f02-2510e328e58a", "source_id": "98469cf2-27e5-5352-a615-5b7be1937da0"}, {"subject_table": "person", "field_path": "description", "claim_text": "本段记贾公铎：出猎并伏兵者。", "citation": "卷260·乾宁三年（896）·zztj-v260-y0896-p018·原文件第99行", "note": "原文：淮南将硃延寿奄至蕲州，围其城。大将贾公鐸方猎，不得还，伏兵林中，命勇士二人衣羊皮夜入延寿所掠羊群，潜入城，约夜半开门举火为应，复衣皮返命。公鐸如期引兵至城南，门中火举，力战，突围而入。延寿惊曰：“吾常恐其溃围而出，反溃围而入，如此，城安可猝拔！”乃白行密，求军中与公鐸有旧者持誓书金帛往说之，许以婚。寿州团练副使柴再用请行，临城与语，为陈利害。数日，公鐸及刺史冯敬章请降。以敬章为左都押牙，公鐸为右监门卫将军。延寿进拔光州，杀刺吏刘存。；核对说明：按本段原文整理，不补写未载的月日、地点或人物完整生平。", "status": "draft", "id": "6fd38e1d-af56-56c0-b6b7-9722ed09adfe", "subject_id": "242f59ca-4d96-5fa7-8b74-51765b84a300", "source_id": "98469cf2-27e5-5352-a615-5b7be1937da0"}, {"subject_table": "person_event", "field_path": "role", "claim_text": "贾公铎：出猎并伏兵者。", "citation": "卷260·乾宁三年（896）·zztj-v260-y0896-p018·原文件第99行", "note": "原文：大将贾公鐸方猎，不得还，伏兵林中；核对说明：按本段原文整理，不补写未载的月日、地点或人物完整生平。", "status": "draft", "id": "3538aa66-2058-5b3f-8965-fc591a90d83d", "subject_id": "ff0da08c-5b36-504a-a00b-0ff56a105be8", "source_id": "98469cf2-27e5-5352-a615-5b7be1937da0"}, {"subject_table": "event", "field_path": "description", "claim_text": "贾公铎命两名勇士穿羊皮，夜入朱延寿掠来的羊群，潜入城中约定夜半开门举火响应，再穿羊皮返回复命。", "citation": "卷260·乾宁三年（896）·zztj-v260-y0896-p018·原文件第99行", "note": "原文：命勇士二人衣羊皮夜入延寿所掠羊群，潜入城，约夜半开门举火为应，复衣皮返命。；核对说明：二勇士未名，不编姓名或人物档案；约夜半是约定，不转换钟点或公历日。", "status": "draft", "id": "bb7bb252-78b6-5793-934c-791554ab085f", "subject_id": "6d6ef884-17b8-55f3-a0e5-e9